using System.Net;
using System.Text.Json;
using System.Text.Json.Nodes;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Hosting;
using Simplic.OxS.Server.Hosting.Test.Fixtures;
using Simplic.OxS.Server.OxSchema;

namespace Simplic.OxS.Server.Hosting.Test
{
    /// <summary>
    /// The OpenAPI document a service built on <see cref="Bootstrap"/> serves, generated by the
    /// package's own setup in a host: what it says of the schema routes, that it says of a
    /// service's own controller what it always said, and that the routes between services stay
    /// out of it. API clients are generated from this document, so every assertion here is one
    /// about a generated client.
    /// </summary>
    public sealed class OpenApiDocumentTests
    {
        /// <summary>The document of a started host, as a client generator fetches it.</summary>
        internal static async Task<JsonObject> DocumentAsync(IHost host, string api = "parcel-api")
        {
            using var client = host.GetTestClient();
            using var answer = await client.GetAsync($"/{api}/v1/swagger/v1/swagger.json");

            var text = await answer.Content.ReadAsStringAsync();

            answer.StatusCode.Should().Be(HttpStatusCode.OK, text);

            return JsonNode.Parse(text)!.AsObject();
        }

        /// <summary>The name of the component schema a schema node points to.</summary>
        internal static string? Reference(JsonNode? schema) => schema?["$ref"]?.GetValue<string>().Split('/')[^1];

        internal static string[] Keys(JsonNode? node) => [.. node!.AsObject().Select(member => member.Key)];

        private static string[] Parameters(JsonNode operation) =>
            [.. (operation["parameters"]?.AsArray() ?? []).Select(parameter => $"{parameter!["in"]!.GetValue<string>()} {parameter["name"]!.GetValue<string>()}")];

        [Fact]
        public async Task TheSchemaRoute_IsDescribedAsAnAnonymousConditionalRead()
        {
            using var host = await BootstrapHost.StartAsync<ParcelStartup>();

            var document = await DocumentAsync(host);
            var route = document["paths"]!["/schema"]!.AsObject();

            Keys(route).Should().Equal("get");

            var get = route["get"]!;

            get["summary"]!.GetValue<string>().Should().Be("The Ox schema document of this service.");
            get["description"]!.GetValue<string>().Should().Contain("https://github.com/simplic/simplic-oxs/blob/master/OX_SCHEMA.md").And.Contain("Anonymous");
            Parameters(get).Should().Equal("header If-None-Match");
            get["parameters"]![0]!["required"].Should().BeNull("a first read has no validator to send");

            // Anonymous on this host: one empty requirement, and no status only credentials can cause.
            get["security"]!.ToJsonString().Should().Be("[{}]");
            Keys(get["responses"]).Should().Equal("200", "304");

            var ok = get["responses"]!["200"]!;

            Keys(ok["content"]).Should().Equal("application/json");
            Reference(ok["content"]!["application/json"]!["schema"]).Should().Be(nameof(OxSchemaDocument));
            ok["headers"]!["ETag"]!["schema"]!["type"]!.GetValue<string>().Should().Be("string");

            var unchanged = get["responses"]!["304"]!;

            unchanged["content"].Should().BeNull("a 304 has no body");
            unchanged["headers"]!["ETag"].Should().NotBeNull();
            unchanged["description"]!.GetValue<string>().Should().Contain("If-None-Match");
        }

        [Fact]
        public async Task TheSchemaRoute_OfAHostThatRequiresAuthorizationForIt_NeedsTheDocumentsCredentials()
        {
            using var host = await BootstrapHost.StartAsync<ParcelStartup>(settings: [("OxSchema:RequireAuthorization", "true")]);

            var get = (await DocumentAsync(host))["paths"]!["/schema"]!["get"]!;

            get["security"].Should().BeNull("the route then needs what the document requires of every route");
            Keys(get["responses"]).Should().Equal("200", "304", "401", "403");
            Keys(get["responses"]!["401"]!["content"]).Should().Equal("application/problem+json");
            Reference(get["responses"]!["401"]!["content"]!["application/problem+json"]!["schema"]).Should().Be("ProblemDetails");
        }

        [Fact]
        public async Task TheAddonsRoute_IsDescribedAsAnAuthorizedConditionalRead()
        {
            using var host = await BootstrapHost.StartAsync<ParcelStartup>();

            var route = (await DocumentAsync(host))["paths"]!["/schema/addons"]!.AsObject();

            Keys(route).Should().Equal("get");

            var get = route["get"]!;

            get["summary"]!.GetValue<string>().Should().Be("The addon definitions of the caller's organisation, per extendable entity.");
            get["description"]!.GetValue<string>().Should().Contain("https://github.com/simplic/simplic-oxs/blob/master/OX_SCHEMA.md");
            Parameters(get).Should().Equal("header If-None-Match");
            get["security"].Should().BeNull("it needs what the document requires of every route");
            Keys(get["responses"]).Should().Equal("200", "304", "401", "403");

            var answer = get["responses"]!["200"]!["content"]!["application/json"]!["schema"]!;

            answer["type"]!.GetValue<string>().Should().Be("object");
            answer["additionalProperties"]!["type"]!.GetValue<string>().Should().Be("array");
            Reference(answer["additionalProperties"]!["items"]).Should().Be(nameof(OxSchemaProperty));

            foreach (var refused in new[] { "401", "403" })
            {
                Keys(get["responses"]![refused]!["content"]).Should().Equal("application/problem+json");
                get["responses"]![refused]!["description"]!.GetValue<string>().Should().NotBeNullOrWhiteSpace();
            }
        }

        [Fact]
        public async Task TheExamplesOfTheSchemaRoutes_AreBodiesOfTheirFormat()
        {
            using var host = await BootstrapHost.StartAsync<ParcelStartup>();

            var paths = (await DocumentAsync(host))["paths"]!;
            var document = paths["/schema"]!["get"]!["responses"]!["200"]!["content"]!["application/json"]!["example"]!;
            var addons = paths["/schema/addons"]!["get"]!["responses"]!["200"]!["content"]!["application/json"]!["example"]!;

            // Every required member is there, and no member the format does not have.
            var strict = new JsonSerializerOptions(OxSchemaJson.Canonical) { UnmappedMemberHandling = System.Text.Json.Serialization.JsonUnmappedMemberHandling.Disallow };
            var read = document.Deserialize<OxSchemaDocument>(strict)!;

            read.SchemaVersion.Should().Be(OxSchemaDocument.CurrentSchemaVersion);
            read.Revision.Should().MatchRegex("^sha256:[0-9a-f]{64}$");
            read.Types.Should().ContainKey("parcel.parcel").WhoseValue.Entity.Should().BeTrue();

            addons.Deserialize<Dictionary<string, List<OxSchemaProperty>>>(strict)!
                .Should().ContainKey("parcel.parcel").WhoseValue.Should().ContainSingle().Which.Kind.Should().Be("string");
        }

        [Fact]
        public async Task TheDocumentOfAServicesOwnController_IsWhatItWasBeforeThePackageDescribedItsRoutes()
        {
            // Kept from a host of the package as it was before it described its own routes.
            var kept = JsonNode.Parse(await File.ReadAllTextAsync(Path.Combine(AppContext.BaseDirectory, "Fixtures", "parcel-openapi.json")))!.AsObject();

            using var host = await BootstrapHost.StartAsync<ParcelStartup>();

            var document = await DocumentAsync(host);
            var schemas = new JsonObject();

            foreach (var name in Keys(kept["components"]!["schemas"]))
                schemas[name] = document["components"]!["schemas"]![name]?.DeepClone();

            var own = new JsonObject
            {
                ["openapi"] = document["openapi"]!.DeepClone(),
                ["info"] = document["info"]!.DeepClone(),
                ["paths"] = new JsonObject(document["paths"]!.AsObject().Where(path => path.Key.StartsWith("/Parcel", StringComparison.Ordinal)).Select(path => KeyValuePair.Create(path.Key, path.Value?.DeepClone()))),
                ["components"] = new JsonObject { ["schemas"] = schemas, ["securitySchemes"] = document["components"]!["securitySchemes"]!.DeepClone() },
                ["security"] = document["security"]!.DeepClone(),
                ["tags"] = new JsonArray([.. document["tags"]!.AsArray().Where(tag => tag!["name"]!.GetValue<string>() == "Parcel").Select(tag => tag!.DeepClone())]),
            };

            JsonNode.DeepEquals(own, kept).Should().BeTrue(
                "the operations, parameters, statuses and models of a service's own controller, and the document's security, are untouched; the document reads\n{0}",
                own.ToJsonString(new JsonSerializerOptions { WriteIndented = true }));

            // The anonymous action of the service keeps the statuses and the security it had: only the package's own routes are described anew.
            var open = document["paths"]!["/Parcel/open"]!["get"]!;

            open["security"].Should().BeNull();
            Keys(open["responses"]).Should().Equal("200", "400", "401", "403", "404", "409", "422", "500");
        }

        [Fact]
        public async Task TheRoutesBetweenServices_AreNotInTheDocument()
        {
            using var host = await BootstrapHost.StartAsync<ParcelStartup>(environment: "Development");

            var document = await DocumentAsync(host);

            Keys(document["paths"]).Should().NotContain(path => path.Contains("internal", StringComparison.OrdinalIgnoreCase));
            Keys(document["components"]!["schemas"]).Should().NotContain(name => name.Contains("ExplainBatch", StringComparison.Ordinal), "the models of the routes between services are not published");
        }

        [Fact]
        public void TheQueryEnginesComments_AreBesideTheAssembliesOfAProjectThatImportsThePackagesTargets()
        {
            File.Exists(Path.Combine(AppContext.BaseDirectory, "OxQL.AspNetCore.xml")).Should().BeTrue(
                "the package's build targets copy the comments of OxQL.AspNetCore beside the assemblies, where the document's setup reads them");
        }
    }
}
